class Solution {
  public int minTravelTime(int l, int n, int k, int[] position, int[] time) {
    int INF = Integer.MAX_VALUE / 2;
    int[] T = new int[n + 1];
    for (int i = 0; i < n; i++) T[i + 1] = T[i] + time[i];
    // dp[b][p][j]: sign b kept, previous kept p (p == n means none), j signs removed so far
    int[][][] dp = new int[n][n + 1][k + 1];
    for (int[][] a : dp) for (int[] b : a) java.util.Arrays.fill(b, INF);
    dp[0][n][0] = 0;
    for (int b = 0; b < n - 1; b++) {
      for (int p = 0; p <= n; p++) {
        int eff = p == n ? T[b + 1] : T[b + 1] - T[p + 1];
        for (int j = 0; j <= k; j++) {
          if (dp[b][p][j] >= INF) continue;
          for (int c = b + 1; c < n; c++) {
            int nj = j + c - b - 1;
            if (nj > k) break;
            int cost = dp[b][p][j] + (position[c] - position[b]) * eff;
            if (cost < dp[c][b][nj]) dp[c][b][nj] = cost;
          }
        }
      }
    }
    int ans = INF;
    for (int p = 0; p < n; p++) ans = Math.min(ans, dp[n - 1][p][k]);
    return ans;
  }
}
